def check_good_function(g, a_vals, b_vals):
    for a in a_vals:
        for b in b_vals:
            if a == b: continue
            # Condition 1
            if g(a*b) == 0:
                if not (g(a) == 0 or g(b) == 0):
                    return False, f"Condition 1 failed for a={a}, b={b}"
            # Condition 2
            if g(a*b) != 0:
                lhs = (g(a) - g(b)) / (a - b)
                rhs = (g(a) * g(b)) / g(a*b)
                if abs(lhs - rhs) > 1e-9:
                    return False, f"Condition 2 failed for a={a}, b={b}"
    return True, "Passed"

